function nextRef(){const y=new Date().toLocaleDateString('en',{timeZone:'Europe/Istanbul',year:'numeric'});db.pcsSeq=db.pcsSeq||{};let ref;do{db.pcsSeq[y]=(db.pcsSeq[y]||0)+1;ref=(SET.get('refPrefix')||'PCS')+y+String(db.pcsSeq[y]).padStart(5,'0')}while(db.declarations.some(d=>d.ref===ref));return ref}
