const FAC_KEY='t1-facility-codes';const facList=()=>{try{return JSON.parse(localStorage.getItem(FAC_KEY)||'[]')}catch{return[]}};

function syncFacility(){const el=form.elements.facilityCode;if(!el)return;const lab=el.closest('label');let row=lab.closest('.aeoRow');if(!row){const al=form.elements.aeo.closest('label');row=document.createElement('div');row.className='aeoRow';al.before(row);row.append(al,lab)}const te=form.elements.transitEnd?.closest('label');if(te&&te.parentElement!==row)row.append(te);const on=form.elements.aeo.checked;lab.hidden=!on;if(te)te.hidden=!on;row.classList.toggle('open',on);{const se=form.elements.seal?.closest('label'),mg=document.querySelector('#moreInfo > .grid');if(se&&mg){if(on){if(se.parentElement!==row){se.classList.add('aeoSeal');row.append(se)}}else if(se.parentElement!==mg){se.classList.remove('aeoSeal');mg.insertBefore(se,form.elements.noSeal?.closest('label')||null)}}}if(on&&!el.value.trim())el.value=(SET.get('facilityCode')||'');let dl=document.getElementById('facilities');if(!dl){dl=document.createElement('datalist');dl.id='facilities';document.body.append(dl);el.setAttribute('list','facilities')}dl.innerHTML=facList().map(c=>'<option value="'+esc(c)+'">').join('')}
