function fillForm(values){for(const [key,,type]of fields){if(type==='repeat'){$('[data-repeat="'+key+'"] .repeatrows').innerHTML='';for(const v of values[key]||[])addRepeat(key,v)}else if(type==='checkbox')form.elements[key].checked=!!values[key];else form.elements[key].value=values[key]??''}form.querySelectorAll('.invalid').forEach(e=>e.classList.remove('invalid'));$('#stepError').hidden=true;syncRoro();syncFacility();$('#singleParties').open=!!(values.sender||values.receiver);operations?.reset()}
