$('#goodDialog').addEventListener('cancel',e=>{if(goodFormDirty){e.preventDefault();closeGood()}});$('#addGood').onclick=()=>openGood();$('#quickAddGood').onclick=()=>{setStep(3);openGood()};$('#goodsCards').onclick=e=>{const b=e.target.closest('[data-good]');if(!b)return;const index=work.records.findIndex(g=>g.id===b.dataset.id);if(index<0)return;if(b.dataset.good==='edit')openGood(b.dataset.id);else if(b.dataset.good==='party')openGood(b.dataset.id,b.dataset.side);else if(b.dataset.good==='hat'){const g=work.records[index],r=hat.createFromGood({mrn:g.mrn,trailer:work.values.trailer,vehicle:work.values.vehicle,office:work.values.departureOffice,declarationRef:work.ref});if(r.error)toast(r.error);else if(r.existing)toast('Bu MRN için hat bildirimi zaten var ('+r.existing.status+'). Hat bildirimleri sayfasından bakabilirsin.');else toast('Hat bildirimi hazırlandı: '+r.created.mrn+'. Hat bildirimleri sayfasında görebilirsin.')}else if(b.dataset.good==='clone')openGood(null,null,seedGood(work.records[index]));else if(b.dataset.good==='remove')confirmAction('Eşya satırını kaldır',work.records[index].mrn+' bu beyannamenin taslağından çıkarılacak.',()=>{work.records.splice(index,1);work.status='Taslak';flushDraft();renderGoods();renderRail()});else{const next=b.dataset.good==='up'?index-1:index+1;if(next<0||next>=work.records.length)return;[work.records[index],work.records[next]]=[work.records[next],work.records[index]];work.status='Taslak';flushDraft();renderGoods();renderRail()}};
