async function autoGuarantor(){if(!work||!form.elements.guarantor)return;const el=form.elements.guarantor;if(el.value.trim())return;let name=SET.get('defGuarantor')||'';if(!name)return;try{const c=(await references.getCompanies()).find(x=>String(x.name||'').toLocaleUpperCase('tr')===String(name).toLocaleUpperCase('tr')||/EUROT[UÜ]RK/i.test(String(x.name||'').replace(/İ/g,'I').replace(/Ü/g,'U'))&&/EUROT/i.test(String(name).replace(/İ/g,'I').replace(/Ü/g,'U')));if(c)name=c.name}catch{}if(!el.value.trim()){el.value=name;queueDraft()}}
function markGuarCalc(){const el=form.elements.guaranteeAmount;if(!el)return;const lab=el.closest('label');if(!lab)return;let b=lab.querySelector('.calcBadge');const auto=work&&work.fin&&work.fin.guaranteeAuto;const on=auto!=null&&Math.abs(num(el.value)-auto)<0.005;if(on&&!b){b=document.createElement('em');b.className='calcBadge';b.textContent='HESAPLANDI';lab.querySelector('span').append(b)}else if(!on&&b)b.remove()}
function applyGuarantee(g,force=false){if(!work||!(g.eur>0))return;const el=form.elements.guaranteeAmount;if(!el)return;const cur=num(el.value),prev=work.fin.guaranteeAuto;if(force||!String(el.value).trim()||(prev!=null&&Math.abs(cur-prev)<0.005)){el.value=String(g.eur).replace('.',',');form.elements.guaranteeCurrency.value='EUR';work.fin.guaranteeAuto=g.eur;queueDraft()}markGuarCalc()}
function renderReview(){work.values=readForm();const v=work.values,t=totals(work.records);reviewProblems=allProblems(v,work.records).map((x,i)=>({...x,problemIndex:i}));$('#reviewHero').classList.toggle('ok',!reviewProblems.length);$('#reviewHero').innerHTML=reviewProblems.length?'<strong>'+reviewProblems.length+' alan kontrolü bekliyor.</strong>Eksik bilgileri aşağıdaki bağlantılardan tamamlayabilirsin. Taslağın kaybolmaz.':'<strong>Alan kontrolleri tamam.</strong>Çıktını indirebilir ve bu kontrolü kaydedebilirsin. Resmî gönderim bağlantısı ayrıca kurulmalıdır.';const stepIssues=i=>reviewProblems.filter(x=>x.step===i);$('#reviewSections').innerHTML=reviewBlock('01 · Gümrükler',0,[['Hareket',v.departureOffice],['Varış',v.arrivalOffice],['Ülkeler',[v.dispatchCountry,v.destinationCountry].filter(Boolean).join(' → ')],['Yükleme / boşaltma',[v.dispatchCountry,v.destinationCountry].filter(Boolean).join(' - ')||[v.loadPlace,v.unloadPlace].filter(Boolean).join(' → ')]],stepIssues(0))+reviewBlock('02 · Müşteri, taşıyıcı ve plakalar',1,[['Müşteri',v.customer],['İzinli gönderici (AEO)',v.aeo?'Evet':'Hayır'],['Taşıyıcı',v.carrier],['Çekici / ülke',[v.vehicle,v.vehicleCountry].filter(Boolean).join(' · ')],['Treyler / ülke',[v.trailer,v.trailerCountry].filter(Boolean).join(' · ')],['Gönderici',v.sender||[...new Set(work.records.map(g=>g.sender).filter(Boolean))].join(' / ')],['Alıcı',v.receiver||[...new Set(work.records.map(g=>g.receiver).filter(Boolean))].join(' / ')]],stepIssues(1))+reviewBlock('03 · Güzergâh ve transit',2,[['Güzergâh',v.routeCountries.join(' → ')],['Transit kapılar',v.transitOffices.join(' → ')],['Sınır gümrüğü',v.borderOffice],['Taşıma modu',v.transportMode],['Konteyner',v.container],['Mühür',v.noSeal?'Mühür yok':v.seal]],stepIssues(2))+reviewBlock('04 · Eşya ve belgeler',3,[['Eşya satırı',String(t.count)],['Toplam brüt / net',fmt(t.gross)+' / '+fmt(t.net)+' kg'],['Toplam kap',fmt(t.packages)],['Fatura dövizleri',[...new Set(work.records.map(g=>g.currency).filter(Boolean))].join(', ')]],stepIssues(3))+reviewBlock('05 · Teminat ve ek bilgiler',4,[['Asıl sorumlu',v.principal],['Garantör / tip',[v.guarantor,v.guaranteeType].filter(Boolean).join(' / ')],['Teminat referansı',v.guaranteeRef],['Tutar',v.guaranteeAmount?fmt(num(v.guaranteeAmount))+' '+v.guaranteeCurrency:''],['Transit bitiş',v.transitEnd]],stepIssues(4))+(()=>{const fl=work.fin?.lines||[],sm=Fin.sums(getFinance(),fl);return reviewBlock('06 · Finansal bilgiler',5,[['Gelir kalemi',String(fl.filter(l=>l.side==='gelir').length)],['Gelir toplamı',Fin.money(sm.gelir)],['Gider toplamı',Fin.money(sm.gider)]],[])})();$('#activityList').innerHTML=(db.declarations.find(d=>d.id===work.id)?.activity||[]).slice().reverse().map(e=>'<p>'+esc(time(e.at))+' · '+esc(e.message)+'</p>').join('')||'<p>Henüz kaydedilmiş işlem yok.</p>'}
