const DASH_KEY='t1-dash-hidden';
function renderDash(){const el=$('#homeDash');if(!el)return;let hidden=false;try{hidden=localStorage.getItem(DASH_KEY)==='1'}catch{}
 const act=db.declarations.filter(d=>!d.archived);const day=86400000,today=new Date();today.setHours(0,0,0,0);
 const days=[...Array(14)].map((_,i)=>{const t=today.getTime()-(13-i)*day;return {t,n:0}});
 for(const d of act){const t=new Date(d.createdAt||d.updatedAt);t.setHours(0,0,0,0);const x=days.find(k=>k.t===t.getTime());if(x)x.n++}
 const max=Math.max(1,...days.map(k=>k.n)),bars=days.map((k,i)=>{const hh=Math.round(k.n/max*64),x=i*20+4;return '<g><title>'+new Date(k.t).toLocaleDateString('tr-TR')+': '+k.n+' beyanname</title><rect x="'+x+'" y="'+(74-hh)+'" width="14" height="'+Math.max(hh,3)+'" rx="5" fill="'+(i===13?'url(#bg1)':(k.n?'#9db7ff':'#e3e8f1'))+'"/>'+(k.n?'<text x="'+(x+7)+'" y="'+(70-hh)+'" text-anchor="middle" font-size="9" font-weight="700" fill="#3b4d73">'+k.n+'</text>':'')+'</g>'}).join('');
 const total14=days.reduce((s,k)=>s+k.n,0);
 const st=[['Taslak',act.filter(d=>d.status==='Taslak').length,'#94a3b8'],['Ön hazırlık',act.filter(d=>d.status==='Ön hazırlık').length,'#8b5cf6'],['Kontrol edildi',act.filter(d=>d.status==='Kontrol edildi').length,'#16a34a']];
 const sum=st.reduce((s,x)=>s+x[1],0),R=38,C=2*Math.PI*R;let off=0;const arcs=sum?st.filter(x=>x[1]).map(x=>{const len=x[1]/sum*C,a='<circle r="'+R+'" cx="55" cy="55" fill="none" stroke="'+x[2]+'" stroke-width="14" stroke-dasharray="'+len+' '+(C-len)+'" stroke-dashoffset="'+(-off)+'" transform="rotate(-90 55 55)" stroke-linecap="butt"/>';off+=len;return a}).join(''):'';
 const due=act.map(d=>({d,n:dueDays(d)})).filter(x=>x.n!==null).sort((a,b)=>a.n-b.n).slice(0,4);
 const inc=$('#incomeSum')?.textContent||'—';
 el.innerHTML='<div class="dashHead"><b>PANEL</b><button type="button" id="dashToggle">'+(hidden?'▾ GÖSTER':'▴ GİZLE')+'</button></div>'+(hidden?'':'<div class="dashGrid">'
  +'<section class="dc"><h3>SON 14 GÜN <small>'+total14+' beyanname</small></h3><svg viewBox="0 0 280 84" class="bars"><defs><linearGradient id="bg1" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3b6cff"/><stop offset="1" stop-color="#22d3ee"/></linearGradient></defs>'+bars+'</svg></section>'
  +'<section class="dc"><h3>DURUM DAĞILIMI</h3><div class="donutW"><svg viewBox="0 0 110 110" class="donut"><circle r="'+R+'" cx="55" cy="55" fill="none" stroke="#eef2f9" stroke-width="14"/>'+arcs+'<text x="55" y="53" text-anchor="middle" font-size="22" font-weight="800" fill="#0b1530" font-family="Plus Jakarta Sans,Inter,sans-serif">'+sum+'</text><text x="55" y="68" text-anchor="middle" font-size="8" letter-spacing="1" fill="#7a88a3">AKTİF</text></svg><ul class="lgd">'+st.map(x=>'<li><i style="background:'+x[2]+'"></i>'+x[0].toLocaleUpperCase('tr')+' <b>'+x[1]+'</b></li>').join('')+'</ul></div></section>'
  +'<section class="dc"><h3>YAKLAŞAN TRANSİT SÜRELERİ</h3>'+(due.length?'<ul class="dueL">'+due.map(x=>'<li><button type="button" data-dueopen="'+esc(x.d.id)+'"><b>'+esc(x.d.ref)+'</b><span>'+esc([x.d.vehicle,x.d.customer].filter(Boolean).join(' · '))+'</span><em class="'+(x.n<0?'late':x.n<=2?'soon':'')+'">'+(x.n<0?Math.abs(x.n)+' GÜN GEÇTİ':x.n===0?'BUGÜN':x.n+' GÜN')+'</em></button></li>').join('')+'</ul>':'<p class="dcEmpty">Transit bitiş tarihi girilmiş beyanname yok.</p>')+'</section>'
  +(()=>{const n=Seals.count(),t=Math.max(1,Seals.total()),low=n<=SET.get('sealLow'),pct=Math.round(n/t*100);return '<section class="dc dcSeal'+(low?' low':'')+'" data-sealcard tabindex="0" role="button" title="Mühür stoğunu aç"><h3>MÜHÜR STOĞU'+(low?' <small>DÜŞÜK</small>':'')+'</h3><strong>'+n+'</strong><small>'+(n?'mühür kullanıma hazır':'stok boş')+'</small><div class="sealBar"><i style="width:'+pct+'%"></i></div><em>'+n+' / '+t+' · %'+pct+'</em></section>'})()+'</div>')}
