$('#declarationRows').onclick=e=>{const b=e.target.closest('[data-open]');if(b){startEditor(b.dataset.open,1);return}const action=e.target.closest('[data-action]');if(!action)return;if(action.dataset.action==='ens'){ens.createFromT1(db.declarations.find(x=>x.id===action.dataset.id));return}if(action.dataset.action==='invoice'){const dd=db.declarations.find(x=>x.id===action.dataset.id);accounting.openInvoiceForDeclaration({...dd,finLines:[...(readGoods(dd.id).fin?.lines||[]),...ens.list().filter(r=>!r.archived&&r.ncts===dd.ref).flatMap(r=>(r.fin?.lines||[]).map(l=>({...l,name:l.name+' (ENS '+r.ref+')'})))].filter(l=>l.side==='gelir')});return}if(action.dataset.action==='addmrn'){startEditor(action.dataset.id,3);openGood();return}const d=db.declarations.find(x=>x.id===action.dataset.id);if(action.dataset.action==='repeat'){const src=db.declarations.find(x=>x.id===action.dataset.id);if(!src)return;const id=crypto.randomUUID(),now=new Date().toISOString(),clone={...src,id,ref:nextRef(),lrn:'',mrn:'',exportMrns:'',status:'Taslak',archived:false,createdAt:now,updatedAt:now,activity:[{at:now,message:src.ref+' kaydından tekrarlandı (eşyasız).'}]};try{localStorage.setItem(goodsKey(id),JSON.stringify({name:clone.ref,records:[],draft:{},fin:null}));db.declarations.push(clone);writeDB();startEditor(id,3);toast(clone.ref+' açıldı: müşteri, plaka ve güzergâh '+src.ref+' ile aynı. Eşyayı ekle.')}catch{toast('Kayıt açılamadı; yedek indir.')}return}if(action.dataset.action==='delete'){confirmAction('Beyannameyi sil',d.ref+' kalıcı olarak silinir (eşya satırları ve finans bilgisi dahil). Fatura ve ENS kayıtları silinmez. Emin misin?',()=>{db.declarations=db.declarations.filter(x=>x.id!==d.id);try{localStorage.removeItem(goodsKey(d.id))}catch{}if(db.draft&&db.draft.id===d.id)db.draft=null;writeDB();renderList();toast(d.ref+' silindi.')});return}if(action.dataset.action==='archive'){d.archived=!d.archived;d.updatedAt=new Date().toISOString();writeDB();renderList();toast(d.archived?'Arşivlendi. Arşiv filtresinden geri alabilirsin.':'Kayıt arşivden çıkarıldı.')}else confirmAction('Beyannameyi kopyala','Yeni bir taslak oluşturulur. Transit LRN/MRN temizlenir, eşya satırları yeniden kontrol bekler.',()=>{const id=crypto.randomUUID(),now=new Date().toISOString(),clone={...d,id,ref:nextRef(),lrn:'',mrn:'',status:'Taslak',archived:false,createdAt:now,updatedAt:now,activity:[{at:now,message:'Önceki beyannameden taslak kopyalandı.'}]};try{localStorage.setItem(goodsKey(id),JSON.stringify({name:clone.ref,records:readGoods(d.id).records.map(g=>({...g,id:crypto.randomUUID(),reviewed:false}))}));db.declarations.push(clone);writeDB();renderList();toast('Yeni taslak kopyalandı.')}catch{toast('Kopya kaydedilemedi; yedek indir.')}})};
